def compute(vars):
    cash = vars["v1"]
    total_purchase_price = vars["v2"]

    if total_purchase_price == 0:
        return None

    portion = cash / total_purchase_price
    return {
        "value": portion,
        "trace": {
            "cash": cash,
            "total_purchase_price": total_purchase_price,
            "output_meta": {
                "currency": None,
                "scale": "ones",
                "unit": "ratio"
            }
        }
    }
